/**
 * Sealed trait hierarchy for recursive JSON values.
 * Replaces Python's Union type with Scala's algebraic data types.
 */
sealed trait JsonValue

object JsonValue {
  case object JsonNull extends JsonValue
  final case class JsonString(value: String) extends JsonValue
  final case class JsonNumber(value: BigDecimal) extends JsonValue
  final case class JsonBoolean(value: Boolean) extends JsonValue
  final case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  final case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  /**
   * Convert from Any to JsonValue.
   */
  def fromAny(value: Any): JsonValue = value match {
    case null => JsonNull
    case s: String => JsonString(s)
    case n: Number => JsonNumber(BigDecimal(n.toString))
    case b: Boolean => JsonBoolean(b)
    case a: Array[Any] => JsonArray(a.map(fromAny).toVector)
    case seq: Iterable[Any] => JsonArray(seq.map(fromAny).toVector)
    case map: Map[String, Any] => JsonObject(map.mapValues(fromAny))
    case other => JsonString(other.toString)
  }
}

/**
 * Tokenizer for JSON structures with support for recursive traversal.
 */
class JsonTokenizer(val pretty: Boolean = false) {
  import JsonValue._

  /**
   * Tokenize a JSON value.
   */
  def tokenize(value: JsonValue): Token = {
    val jsonStr = toJsonString(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /**
   * Extract and tokenize a value at a JSON path.
   * Path uses dot notation (e.g., "field.subfield.0")
   */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    val result = parts.foldLeft(Option(value)) { case (current, part) =>
      current.flatMap {
        case JsonObject(fields) =>
          fields.get(part)
        case JsonArray(values) =>
          Try(part.toInt).toOption.flatMap { idx =>
            if (idx >= 0 && idx < values.length) Some(values(idx)) else None
          }
        case _ => None
      }
    }
    result.map(tokenize)
  }

  /**
   * Convert JsonValue to JSON string.
   */
  private def toJsonString(value: JsonValue): String = {
    def stringify(jv: JsonValue, indent: Int = 0): String = {
      val padding = if (pretty) "  " * indent else ""
      val nextPadding = if (pretty) "  " * (indent + 1) else ""
      val newline = if (pretty) "\n" else ""
      val space = if (pretty) " " else ""

      jv match {
        case JsonNull => "null"
        case JsonString(s) => "\"" + escapeString(s) + "\""
        case JsonNumber(n) => n.toString
        case JsonBoolean(b) => b.toString
        case JsonArray(values) =>
          if (values.isEmpty) "[]"
          else {
            val items = values.map(v => nextPadding + stringify(v, indent + 1)).mkString("," + newline)
            "[" + newline + items + newline + padding + "]"
          }
        case JsonObject(fields) =>
          if (fields.isEmpty) "{}"
          else {
            val items = fields.map { case (k, v) =>
              nextPadding + "\"" + escapeString(k) + "\":" + space + stringify(v, indent + 1)
            }.mkString("," + newline)
            "{" + newline + items + newline + padding + "}"
          }
      }
    }

    stringify(value)
  }

  /**
   * Escape special characters in JSON strings.
   */
  private def escapeString(s: String): String = {
    s.flatMap {
      case '"' => "\\\""
      case '\\' => "\\\\"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case '\b' => "\\b"
      case '\f' => "\\f"
      case c => c.toString
    }
  }
}

