/**
 * Utility object for batch tokenization operations.
 */
object BatchTokenizer {
  /**
   * Tokenize a large collection efficiently using Iterator.
   */
  def tokenizeLazy[T](tokenizer: BaseTokenizer[T], values: Iterable[T]): Iterator[Token] =
    tokenizer.tokenizeBatch(values)

  /**
   * Tokenize with parallel processing for large datasets.
   * Useful for distributed systems.
   */
  def tokenizeParallel[T](
    tokenizer: BaseTokenizer[T],
    values: Iterable[T],
    parallelism: Int = 4
  ): Vector[Token] = {
    values
      .grouped(Math.max(1, values.size / parallelism))
      .par
      .flatMap(group => tokenizer.tokenizeBatchCollect(group))
      .toVector
  }

  /**
   * Tokenize with error handling for each item.
   */
  def tokenizeSafe[T](
    tokenizer: BaseTokenizer[T],
    values: Iterable[T]
  ): Vector[Either[Throwable, Token]] = {
    values.map { value =>
      Try(tokenizer.tokenize(value)).toEither
    }.toVector
  }
}

