import java.time.{LocalDate, LocalDateTime, ZonedDateTime}
import java.time.format.DateTimeFormatter
import scala.util.{Try, Success, Failure}

// ============================================================================
// Token Type Enumeration
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation with optional metadata.
 */
final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata merged with existing metadata.
   */
  def withMetadata(newMeta: (String, Any)*): Token =
    this.copy(metadata = metadata ++ newMeta.toMap)

  /**
   * Create a new token with completely replaced metadata.
   */
  def withMetadataMap(newMeta: Map[String, Any]): Token =
    this.copy(metadata = newMeta)
}

/**
 * Mutable batch container for tokens - useful for batch processing.
 * Prevents modifications after marking as processed.
 */
class MutableTokenBatch {
  private var tokens: Vector[Token] = Vector.empty
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: Vector[Token] = tokens

  def isProcessed: Boolean = _processed
}

// ============================================================================
// Type Classes for Polymorphism
// ============================================================================

/**
 * Type class for types that can be converted to tokens.
 */
trait Tokenizable[A] {
  def toToken(value: A): String
}

/**
 * Type class for types with length.
 */
trait HasLength[A] {
  def length(value: A): Int
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can be read and return subtypes.
 * Immutable and thread-safe.
 */
final class TokenContainer[+A](private val items: Vector[A]) {
  def getAll: Vector[A] = items

  def map[B](f: A => B): TokenContainer[B] =
    new TokenContainer(items.map(f))

  def mapTokens(f: A => String): Vector[String] =
    items.map(f)

  def length: Int = items.length

  def isEmpty: Boolean = items.isEmpty

  def nonEmpty: Boolean = items.nonEmpty
}

object TokenContainer {
  def apply[A](items: A*): TokenContainer[A] =
    new TokenContainer(items.toVector)

  def fromIterable[A](items: Iterable[A]): TokenContainer[A] =
    new TokenContainer(items.toVector)
}

/**
 * Contravariant sink - can accept supertypes.
 * Collects values for later retrieval.
 */
class TokenSink[-A] {
  private var received: Vector[A] = Vector.empty

  def receive(item: A): Unit = {
    received = received :+ item
  }

  def drain(): Vector[A] = {
    val result = received
    received = Vector.empty
    result
  }

  def size: Int = received.length
}

/**
 * Invariant handler - exact type matching required.
 * Allows getting, setting, and transforming a value.
 */
class BivariantHandler[A](private var _value: A) {
  def get: A = _value

  def set(value: A): Unit = {
    _value = value
  }

  def transform(f: A => A): A = {
    _value = f(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Trait (Abstract Base)
// ============================================================================

/**
 * Abstract base trait for tokenizers with generic input type.
 */
trait BaseTokenizer[T] {
  /**
   * Convert a single value to a token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   * Returns an iterator for memory efficiency.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Batch tokenization returning collected results.
   */
  def tokenizeBatchCollect(values: Iterable[T]): Vector[Token] =
    tokenizeBatch(values).toVector
}

// ============================================================================
// Concrete Tokenizer Implementations
// ============================================================================

/**
 * Tokenizer for string and bytes types.
 */
class StringTokenizer(
  val encoding: String = "UTF-8",
  val normalizer: String => String = identity
) extends BaseTokenizer[String] {
  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.STRING)
  }

  /**
   * Alternative method for bytes input.
   */
  def tokenizeBytes(value: Array[Byte]): Token = {
    val str = new String(value, encoding)
    tokenize(str)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
  val precision: Int = 6,
  val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[BigDecimal] {

  /**
   * Tokenize BigDecimal values.
   */
  def tokenize(value: BigDecimal): Token = {
    val str = value.setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString
    Token(str, TokenType.NUMERIC, Map("original_type" -> "BigDecimal"))
  }

  /**
   * Tokenize Int values.
   */
  def tokenizeInt(value: Int): Token = {
    Token(value.toString, TokenType.NUMERIC, Map("original_type" -> "Int"))
  }

  /**
   * Tokenize Double values.
   */
  def tokenizeDouble(value: Double): Token = {
    val str = s"%.${precision}f".format(value)
    Token(str, TokenType.NUMERIC, Map("original_type" -> "Double"))
  }

  /**
   * Tokenize Long values.
   */
  def tokenizeLong(value: Long): Token = {
    Token(value.toString, TokenType.NUMERIC, Map("original_type" -> "Long"))
  }
}

/**
 * Tokenizer for temporal types (dates and times).
 */
class TemporalTokenizer(
  val formatStr: Option[String] = None
) extends BaseTokenizer[LocalDate] {

  private val isoFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  /**
   * Tokenize LocalDate values.
   */
  def tokenize(value: LocalDate): Token = {
    val str = value.format(dateFormatter)
    Token(str, TokenType.TEMPORAL)
  }

  /**
   * Tokenize LocalDateTime values.
   */
  def tokenizeDateTime(value: LocalDateTime): Token = {
    val formatter = formatStr.map(DateTimeFormatter.ofPattern(_)).getOrElse(isoFormatter)
    val str = value.format(formatter)
    Token(str, TokenType.TEMPORAL)
  }

  /**
   * Tokenize ZonedDateTime values.
   */
  def tokenizeZonedDateTime(value: ZonedDateTime): Token = {
    val formatter = formatStr.map(DateTimeFormatter.ofPattern(_)).getOrElse(isoFormatter)
    val str = value.format(formatter)
    Token(str, TokenType.TEMPORAL)
  }

  /**
   * Tokenize with custom formatter.
   */
  def tokenizeWithCustomFormatter(value: LocalDateTime, formatter: DateTimeFormatter): Token = {
    val str = value.format(formatter)
    Token(str, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer with Type Class-based Dispatch
// ============================================================================

/**
 * Tokenizer that handles multiple types with ad-hoc polymorphism.
 * Uses type classes and pattern matching instead of runtime type checks.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
   * Tokenize values of various types.
   * Dispatches based on runtime type using pattern matching.
   */
  def tokenize(value: Any): Token = value match {
    case null =>
      Token("NULL", TokenType.NULL)

    case s: String =>
      stringTokenizer.tokenize(s)

    case b: Array[Byte] =>
      stringTokenizer.tokenizeBytes(b)

    case i: Int =>
      numericTokenizer.tokenizeInt(i)

    case l: Long =>
      numericTokenizer.tokenizeLong(l)

    case d: Double =>
      numericTokenizer.tokenizeDouble(d)

    case bd: BigDecimal =>
      numericTokenizer.tokenize(bd)

    case ld: LocalDate =>
      temporalTokenizer.tokenize(ld)

    case ldt: LocalDateTime =>
      temporalTokenizer.tokenizeDateTime(ldt)

    case zdt: ZonedDateTime =>
      temporalTokenizer.tokenizeZonedDateTime(zdt)

    case t: Tokenizable[_] =>
      // For tokenizable objects, call the toToken method
      Token(t.asInstanceOf[Tokenizable[Any]].toToken(value), TokenType.STRUCTURED)

    case other =>
      // Fallback: convert to string
      Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }

  /**
   * Tokenize a batch of mixed-type values.
   */
  def tokenizeMixed(values: Iterable[Any]): Vector[Token] =
    values.iterator.map(tokenize).toVector
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Supports normalization options like lowercasing and punctuation stripping.
 */
class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {

  private val punctuation = Set(".,!?;:'\"()[]{}")

  /**
   * Process a single word into a token string.
   * Applies filtering and normalization options.
   */
  private def processToken(word: String): Option[String] = {
    val step1 = if (stripPunctuation) {
      word.filterNot(c => punctuation.contains(c.toString))
    } else {
      word
    }

    val step2 = if (lowercase) step1.toLowerCase else step1

    if (step2.length < minLength) {
      None
    } else {
      val step3 = maxLength.map(max => step2.take(max)).getOrElse(step2)
      if (step3.nonEmpty) Some(step3) else None
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): Vector[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }.toVector
  }

  /**
   * Split text and return just the token strings.
   */
  def tokenizeToStrings(text: String): Vector[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   * Returns tuples of (token_string, start_pos, end_pos).
   */
  def tokenizeWithPositions(text: String): Vector[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    var currentPos = 0
    val result = scala.collection.mutable.ArrayBuffer[(String, Int, Int)]()

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word) match {
        case Some(processed) =>
          result += ((processed, start, end))
        case None => ()
      }

      currentPos = end
    }

    result.toVector
  }

  /**
   * Count the number of tokens in text.
   */
  def countTokens(text: String): Int =
    tokenize(text).length
}

// ============================================================================
// Token Registry - Generic Container for Tokens
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Manages containers of tokens and applies handlers.
 */
class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: Vector[T => Option[Token]] = Vector.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry = registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers = handlers :+ handler
  }

  def process(key: String): Vector[Option[Token]] = {
    registry.get(key) match {
      case None => Vector.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.view.map(handler => handler(item)).find(_.isDefined).flatten
        }
    }
  }

  def processAll: Vector[Option[Token]] = {
    registry.values.flatMap { container =>
      container.getAll.map { item =>
        handlers.view.map(handler => handler(item)).find(_.isDefined).flatten
      }
    }.toVector
  }
}

// ============================================================================
// Functor and Monad Structures
// ============================================================================

/**
 * Functor trait for token-like structures.
 * Enables functional composition and transformation.
 */
trait TokenFunctor[+A] {
  def map[B](f: A => B): TokenFunctor[B]

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B]

  def getOrElse[B >: A](default: => B): B
}

/**
 * Box implementation of TokenFunctor.
 * Wraps a single value and provides monadic operations.
 */final case class TokenBox[A](value: Option[A]) extends TokenFunctor[A] {
  def map[B](f: A => B): TokenFunctor[B] =
    TokenBox(value.map(f))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] =
    value match {
      case Some(a) =>
        f(a) match {
          case TokenBox(b) => TokenBox(b)
        }
      case None =>
        TokenBox(None)
    }

  def getOrElse[B >: A](default: => B): B =
    value.getOrElse(default)
}

object TokenBox {
  def pure[A](value: A): TokenBox[A] = TokenBox(Some(value))

  def empty[A]: TokenBox[A] = TokenBox(None)
}

/**
 * Monad extension with applicative operations.
 */
final case class TokenMonad[A](value: Option[A]) extends TokenFunctor[A] {
  def map[B](f: A => B): TokenFunctor[B] =
    TokenMonad(value.map(f))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] =
    value match {
      case Some(a) =>
        f(a) match {
          case TokenMonad(b) => TokenMonad(b)
          case other => TokenMonad(None)
        }
      case None =>
        TokenMonad(None)
    }

  def getOrElse[B >: A](default: => B): B =
    value.getOrElse(default)

  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    this.flatMap { a =>
      funcWrapped.flatMap { f =>
        TokenMonad.pure(f(a))
      }
    } match {
      case TokenMonad(result) => TokenMonad(result)
    }
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = TokenMonad(Some(value))

  def empty[A]: TokenMonad[A] = TokenMonad(None)
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating custom tokenizers.
 * Supports chaining operations and composition.
 */
class TokenizerBuilder[T] {
  private var normalizers: Vector[String => String] = Vector.empty
  private var validators: Vector[T => Boolean] = Vector.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(meta: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ meta.toMap
    this
  }

  /**
   * Build the final tokenizer function.
   * Returns a function that tokenizes values with validation and normalization.
   */
  def build: T => Token = { value =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.STRING, metadata)
  }

  /**
   * Build with error handling using Try.
   */
  def buildSafe: T => Try[Token] = { value =>
    Try {
      build(value)
    }
  }
}

object TokenizerBuilder {
  def apply[T]: TokenizerBuilder[T] = new TokenizerBuilder[T]
}

